// Manual reproduction/sanity-check for the partial-update fix.
// Uses jiti to load .ts files directly.
import { createJiti } from "/c/Users/cooll/Documents/code/frontier-verifier/node_modules/jiti/lib/jiti.mjs";

const jiti = createJiti(import.meta.url, { interopDefault: true, esmResolve: true });
const mod = await jiti.import("./src/task-manager.ts", { default: true });
const { TaskManager } = mod;

function assertEq(actual, expected, msg) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    console.error(`FAIL ${msg}: expected ${e}, got ${a}`);
    process.exitCode = 1;
  } else {
    console.log(`PASS ${msg}`);
  }
}

const tm = new TaskManager();

// Case 1: update only title preserves description and priority
{
  const t = tm.createTask({ title: "Orig", priority: 2, description: "desc" });
  const u = tm.updateTask(t.id, { title: "Updated" });
  assertEq({ title: u.title, description: u.description, priority: u.priority }, { title: "Updated", description: "desc", priority: 2 }, "case1 only title");
}

// Case 2: update only status preserves title and priority
{
  const t = tm.createTask({ title: "t", priority: 1 });
  const u = tm.updateTask(t.id, { status: "completed" });
  assertEq({ title: u.title, priority: u.priority, status: u.status }, { title: "t", priority: 1, status: "completed" }, "case2 only status");
}

// Case 3: update with dueDate null preserves description
{
  const t = tm.createTask({ title: "t3", priority: 3, description: "kept" });
  const u = tm.updateTask(t.id, { dueDate: "2025-01-01" });
  assertEq({ description: u.description, dueDate: u.dueDate }, { description: "kept", dueDate: "2025-01-01" }, "case3 dueDate set");
}

// Case 4: explicitly setting dueDate to null is preserved (null != undefined)
{
  const t = tm.createTask({ title: "t4", priority: 3, dueDate: "2025-01-01" });
  const u = tm.updateTask(t.id, { dueDate: null });
  assertEq(u.dueDate, null, "case4 dueDate null explicit");
}

// Case 5: update with empty object leaves everything intact
{
  const t = tm.createTask({ title: "t5", priority: 3, description: "kept5", dueDate: "2025-01-01" });
  const u = tm.updateTask(t.id, {});
  assertEq({ title: u.title, priority: u.priority, description: u.description, dueDate: u.dueDate, status: u.status },
    { title: "t5", priority: 3, description: "kept5", dueDate: "2025-01-01", status: "pending" }, "case5 empty update");
}

// Case 6: update with description "" explicit (empty string, not undefined)
{
  const t = tm.createTask({ title: "t6", priority: 3, description: "kept6" });
  const u = tm.updateTask(t.id, { description: "" });
  assertEq(u.description, "", "case6 explicit empty string preserved");
}

// Case 7: validation still triggers for invalid values
{
  const t = tm.createTask({ title: "t7", priority: 3 });
  let threw = false;
  try { tm.updateTask(t.id, { priority: 9 as any }); } catch (e) { threw = true; }
  assertEq(threw, true, "case7 invalid priority throws");
}

// Case 8: updatedAt advances on update
{
  const t = tm.createTask({ title: "t8", priority: 3 });
  await new Promise(r => setTimeout(r, 10));
  const u = tm.updateTask(t.id, { title: "t8-new" });
  assertEq(u.updatedAt > t.updatedAt, true, "case8 updatedAt advanced");
}

console.log("DONE");

